import{_ as a,o as t,c as r,a3 as _}from"./chunks/framework.DdpBa4_E.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/xialiu-shehui/83-孩子必须选择自己的生活方式.md","filePath":"books/xialiu-shehui/83-孩子必须选择自己的生活方式.md","lastUpdated":1794732511000}'),o={name:"books/xialiu-shehui/83-孩子必须选择自己的生活方式.md"};function p(s,e,i,n,l,c){return t(),r("div",null,[...e[0]||(e[0]=[_('<h2 id="孩子必须选择自己的生活方式" tabindex="-1">孩子必须选择自己的生活方式 <a class="header-anchor" href="#孩子必须选择自己的生活方式" aria-label="Permalink to &quot;孩子必须选择自己的生活方式&quot;">​</a></h2><p>在笔者的熟人当中，有一对住在东京远郊的奥多摩、过着嬉皮士般生活的夫妇。他们俩都是非常风趣的人，妻子为人善良，丈夫则毕业于一流大学，颇有才华。丈夫的工作是写作，间或会有一两本书出版，而且是那种很有个性的书，然而书越是有个性，收入可能就越少。</p><p>那对夫妇最近有了孩子。当然孩子只接受公立教育，可能根本不会去上私塾或是课外补习班，因为他的父母从来就不喜欢那种类型的教育。</p><p>尽管父母是嬉皮士，但孩子将来长大后是否也愿意步他们的后尘却未可知。就算父母都很优秀，也不能强求孩子的人生同样精彩。父母想要我行我素，按照自己的方式过着悠闲自在的生活，可是不能强求孩子也接受那样的价值观。父母、政府机构以及整个社会，都有义务为孩子准备尽可能多样化的人生选择。对于嬉皮士的孩子，也应该为他们开创将来活跃于世界舞台的可能性，使其成长为国际通用型的人才。</p><p>令人担忧的是，团块次代女性那种“让孩子拥有一技之长，以便能够按照自己的价值观生活”的教育观念，是否真的能够为孩子创造美好的将来？或者也存在另一种可能性，那就是父母本身就觉得自己的孩子无法成为国际通用型的人才，因而选择了放弃。</p><p>因此就产生了一个悬念：当团块次代女性的孩子长大成人时，眼下正在日益扩大的阶层差别是否会进一步扩大、进一步固化，从而演变为一个彻彻底底的“阶层化社会”？</p><p>本书由“<a href="http://epubw.com" target="_blank" rel="noreferrer">ePUBw.COM</a>”整理，<a href="http://epubw.com" target="_blank" rel="noreferrer">ePUBw.COM</a> 提供最新最全的优质电子书下载！！！</p>',7)])])}const u=a(o,[["render",p]]);export{d as __pageData,u as default};
